#include <stdio.h>

int main() {
    char c = 'A';
    short s = 32000;
    int i = 2000000000;
    long long l = 9000000000LL;

    printf("char: %c (%d), size: %zu\n", c, c, sizeof(c));
    printf("short: %d, size: %zu\n", s, sizeof(s));
    printf("int: %d, size: %zu\n", i, sizeof(i));
    printf("long long: %lld, size: %zu\n", l, sizeof(l));

    return 0;
}
